import type { ChartProps } from "./chart.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Chart";

// Generate child element class names for the component, should match available style slots
export const ChartClasses = {
  root: "exp-textura_chart",
  responsiveContainer: "exp-textura_chart_responsive_container",
  barChart: "exp-textura_chart_bar_chart",
  bar: "exp-textura_chart_bar",
  barLabel: "exp-textura_chart_bar_label",
  internalBarLabel: "exp-textura_chart_internal_bar_label",
  lineChart: "exp-textura_chart_line_chart",
  line: "exp-textura_chart_line",
  lineLabel: "exp-textura_chart_line_label",
  donutChart: "exp-textura_chart_donut_chart",
  pieActiveLabel: "exp-textura_chart_pie_active_label",
  areaChart: "exp-textura_chart_area_chart",
  area: "exp-textura_chart_area",
  xAxisLabel: "exp-textura_chart_x_axis_label",
  yAxisLabel: "exp-textura_chart_y_axis_label",
  legendWrapper: "exp-textura_chart_legend_wrapper",
  legend: "exp-textura_chart_legend",
  legendVertical: "exp-textura_chart_legend_vertical",
  legendCenterAlign: "exp-textura_chart_legend_center_align",
  legendTitle: "exp-textura_chart_legend_title",
  legendList: "exp-textura_chart_legend_list",
  legendItem: "exp-textura_chart_legend_item",
  legendColor: "exp-textura_chart_legend_color",
  legendDashedColor: "exp-textura_chart_legend_dashed_color",
  legendLineIcon: "exp-textura_chart_legend_line_icon",
  legendLabel: "exp-textura_chart_legend_label",
  legendSubLabel: "exp-textura_chart_legend_sub_label",
  legendDashboard: "exp-textura_chart_legend_dashboard",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: ChartProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<ChartProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(),
      ),
    [theme, variant, styleSlotsProp],
  );
  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "block",

    ".recharts-surface": {
      borderRadius: theme.toRem(theme.border.radius.sm),
      backgroundColor: theme.color.background.default,
      padding: theme.toRem(theme.spacing[8]),
      outline: "none",
      ...styleSlots?.surface,
    },

    ".recharts-legend-item-text, .recharts-text": {
      ...theme.typography.body.sm,
      ...styleSlots?.text,
    },

    [`.${ChartClasses.responsiveContainer}`]: {
      ...styleSlots?.responsiveContainer,
    },

    [`.${ChartClasses.barChart}`]: {
      ...styleSlots?.barChart,
    },

    [`.${ChartClasses.bar}`]: {
      ...styleSlots?.bar,
    },

    [`.${ChartClasses.barLabel}`]: {
      ...theme.typography.body.sm,
      ...styleSlots?.barLabel,
    },

    [`.${ChartClasses.internalBarLabel}`]: {
      ...theme.typography.body.smEmphasis,
      ...styleSlots?.internalBarLabel,
    },

    [`.${ChartClasses.lineChart}`]: {
      ...styleSlots?.lineChart,
    },

    [`.${ChartClasses.line}`]: {
      ...styleSlots?.line,
    },

    [`.${ChartClasses.lineLabel}`]: {
      ...theme.typography.body.sm,
      ...styleSlots?.lineLabel,
    },

    [`.${ChartClasses.donutChart}`]: {
      ...styleSlots?.donutChart,
    },

    [`.${ChartClasses.areaChart}`]: {
      ...styleSlots?.areaChart,
    },

    [`.${ChartClasses.area}`]: {
      ...styleSlots?.area,
    },

    [`.recharts-pie`]: {
      ...styleSlots?.pie,
    },

    [`.${ChartClasses.pieActiveLabel}`]: {
      ...styleSlots?.pieActiveLabel,
    },

    [`.${ChartClasses.xAxisLabel}`]: {
      ...theme.typography.label.sm,
      fill: theme.color.content.default,
      textAnchor: "middle",
      ...styleSlots?.xAxisLabel,
    },

    [`.${ChartClasses.yAxisLabel}`]: {
      ...theme.typography.label.sm,
      fill: theme.color.content.default,
      textAnchor: "middle",
      ...styleSlots?.yAxisLabel,
    },

    [`.${ChartClasses.legendWrapper}`]: {
      ...styleSlots?.legendWrapper,
    },

    [`.${ChartClasses.legend}`]: {
      width: "fit-content",
      flexDirection: "row",
      flexWrap: "wrap",
      gap: theme.toRem(theme.spacing[16]),
      ...styleSlots?.legend,

      [`&.${ChartClasses.legendDashboard}`]: {
        width: "100%",
      },
    },

    [`.${ChartClasses.legendVertical}`]: {
      display: "flex",
      flexDirection: "column",
      gap: theme.toRem(4),
      ...styleSlots?.legendVertical,
    },

    [`.${ChartClasses.legendList}`]: {
      listStyle: "none",
      padding: 0,
      margin: 0,
      display: "flex",
      flexDirection: "row",
      gap: theme.toRem(theme.spacing[24]),
      ...styleSlots?.legendList,

      [`&.${ChartClasses.legendVertical}`]: {
        flexDirection: "column",
        gap: theme.toRem(2),
        ...styleSlots?.legendVertical,
      },

      [`&.${ChartClasses.legendDashboard}`]: {
        justifyContent: "space-between",
        width: "100%",
        ...styleSlots?.legendDashboard,
      },
    },

    [`.${ChartClasses.legendItem}`]: {
      display: "flex",
      alignItems: "flex-start",
      gap: theme.toRem(theme.spacing[12]),
      ...styleSlots?.legendItem,
    },

    [`.${ChartClasses.legendColor}`]: {
      width: theme.toRem(theme.spacing[16]),
      height: theme.toRem(theme.spacing[16]),
      borderRadius: theme.toRem(theme.border.radius.sm),
      display: "inline-block",
      ...styleSlots?.legendColor,
    },

    [`.${ChartClasses.legendDashedColor}`]: {
      border: "2px dashed",
      backgroundColor: "transparent",
      ...styleSlots?.legendDashedColor,
    },

    [`.${ChartClasses.legendLineIcon}`]: {
      width: theme.toRem(20),
      height: 0,
      borderTop: "3px solid",
      display: "inline-block",
      ...styleSlots?.legendLineIcon,
    },

    [`.${ChartClasses.legendLabel}`]: {
      ...theme.typography.body.sm,
      color: theme.color.content.default,
      fontWeight: theme.typography.fontWeight[600],
      ...styleSlots?.legendLabel,
    },

    [`.${ChartClasses.legendSubLabel}`]: {
      ...theme.typography.label.sm,
      // color: theme.color.content.weak,
      marginTop: theme.toRem(2),
      ...styleSlots?.legendSubLabel,
    },

    [`.${ChartClasses.legendCenterAlign}`]: {
      margin: "0 auto",
      ...styleSlots?.legendCenterAlign,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledChart = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<ChartProps>((props) => generateStyles(props));
